"""Build the standalone design handoff; uses only the Python standard library.

This renders documentation, not the Rho application or an executable UI plugin.
Run from any directory: python3 docs/design/2026-10-26/build.py
"""
from pathlib import Path
import html

ROOT=Path(__file__).resolve().parents[3]
OUT=ROOT/'docs/design/2026-10-26/index.html'
pages=[]
def badge(text,kind='proposal'): return f'<span class="badge {kind}">{text}</span>'
def box(title,body,cls=''): return f'<div class="box {cls}"><h3>{title}</h3>{body}</div>'
def p(text): return f'<p>{text}</p>'
def li(items): return '<ul>'+''.join(f'<li>{v}</li>' for v in items)+'</ul>'
def table(headers,rows,cls=''):
    return f'<table class="doc-table {cls}"><thead><tr>'+''.join(f'<th>{v}</th>' for v in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join(f'<td>{v}</td>' for v in row)+'</tr>' for row in rows)+'</tbody></table>'
def page(title,section,lead,body,cls=''):
    n=len(pages)+1
    pages.append(f'<section class="page {cls}" id="p{n:02d}" aria-label="{n}. {title}"><header><div class="eyebrow">RHO / DESIGN HANDOFF <span>{section}</span></div><h1>{title}</h1><p class="lead">{lead}</p></header><div class="page-body">{body}</div><footer><span>2026-10-26 · 新设计提案 v0.1 · UI 文案为 English，研究内容保留原文</span><span>{n:02d} / 20</span></footer></section>')
def toolbar(*items): return '<div class="toolbar">'+''.join(f'<span class="ui-btn">{i}</span>' for i in items)+'</div>'
def tabs(*names): return '<div class="tabs">'+''.join(f'<span class="tab {"active" if i==0 else ""}">{v}</span>' for i,v in enumerate(names))+'</div>'
def frame(title,body,subtitle='',actions='Details ···',cls=''):
    return f'<div class="view {cls}"><div class="view-head"><div><b>{title}</b>{f"<small>{subtitle}</small>" if subtitle else ""}</div><span class="quiet">{actions}</span></div>{body}</div>'
def note(label,text,cls=''): return f'<div class="note {cls}"><b>{label}</b><span>{text}</span></div>'
def app(body,section='Inclusion rules',inspector='',cls=''):
    return f'''<div class="app {cls}"><aside class="rail"><div class="brand"><span>ρ</span> Rho</div><div class="project-select">Airquality study <span>⌄</span></div><div class="nav-item">Overview</div><div class="nav-item">Files</div><div class="nav-item">Activity <span class="dot"></span></div><div class="nav-label">WORKSPACES</div><div class="nav-item chosen">Inclusion rules</div><div class="nav-item">Figures</div><div class="rail-bottom">Project settings<br><br>Plugins</div></aside><main class="app-main"><div class="app-top"><span>Airquality study <span class="quiet">/</span> {section}</span><span class="top-actions">Search <kbd>⌘ K</kbd><span class="ui-btn">Agent</span></span></div><div class="app-work">{body}{f'<aside class="inspector">{inspector}</aside>' if inspector else ''}</div><div class="app-status"><span>Connected</span><span>Project files stay on this machine</span></div></main></div>'''
def data_table(compare=False):
    if compare:
        heads=['Month','n · Before → After','Mean ozone · Before → After','Δ ppb']
        rows=[['May','24 → <b>26</b>','24.125 → <b>23.615</b>','−0.510'],['June','9 → 9','29.444 → 29.444','0.000'],['July','26 → 26','59.115 → 59.115','0.000'],['August','23 → <b>26</b>','60.000 → <b>59.962</b>','−0.038'],['September','29 → 29','31.448 → 31.448','0.000']]
    else:
        heads=['Month','n','Mean ozone (ppb)']
        rows=[['May','24','24.125'],['June','9','29.444'],['July','26','59.115'],['August','23','60.000'],['September','29','31.448']]
    return '<table class="data"><thead><tr>'+''.join(f'<th>{v}</th>' for v in heads)+'</tr></thead><tbody>'+''.join(f'<tr class="{"changed" if i in ([0,3] if compare else [0]) else ""}">'+''.join(f'<td>{v}</td>' for v in row)+'</tr>' for i,row in enumerate(rows))+'</tbody></table>'
def chart(scatter=False):
    if scatter:
        marks=''.join(f'<circle cx="{x}" cy="{y}" r="{8 if i==0 else 6}" fill="{"#186c57" if i==0 else "#a5bdb5"}" stroke="{"#123d32" if i==0 else "none"}" stroke-width="2"/>' for i,(x,y) in enumerate([(125,230),(175,210),(225,92),(275,88),(325,196)]))
        return f'<svg class="chart" viewBox="0 0 440 300" role="img" aria-label="Illustrative monthly scatterplot with May selected"><path d="M60 30V250H400" fill="none" stroke="#bcc8c3"/>{marks}<text x="102" y="212">May</text><text x="185" y="286">Month</text><text x="20" y="20">Ozone (ppb)</text><text x="340" y="20" class="svg-small">Illustration</text></svg>'
    return '''<svg class="chart" viewBox="0 0 490 290" role="img" aria-label="Illustrative monthly ozone chart"><g stroke="#e2e8e4" stroke-width="1"><path d="M45 55H465 M45 125H465 M45 195H465"/></g><path d="M45 25V245H465" fill="none" stroke="#b5c2bb"/><path d="M80 203L165 188L250 72L335 69L420 180" fill="none" stroke="#a3ada8" stroke-width="3" stroke-dasharray="6 5"/><path d="M80 206L165 188L250 72L335 69.3L420 180" fill="none" stroke="#186c57" stroke-width="3"/><g fill="#186c57"><circle cx="80" cy="206" r="5"/><circle cx="165" cy="188" r="5"/><circle cx="250" cy="72" r="5"/><circle cx="335" cy="69.3" r="5"/><circle cx="420" cy="180" r="5"/></g><g><text x="64" y="270">May</text><text x="150" y="270">Jun</text><text x="238" y="270">Jul</text><text x="321" y="270">Aug</text><text x="405" y="270">Sep</text><text x="45" y="18">Mean ozone (ppb)</text><text x="363" y="18" class="svg-small">Illustration</text></g><rect x="55" y="178" width="60" height="58" fill="#186c5710" stroke="#186c57" stroke-width="1.5" stroke-dasharray="5 4"/><text x="120" y="231" class="svg-small">Selected region</text></svg>'''
def answer(compact=False):
    return f'''<div class="answer"><div class="eyebrow small">ANSWER <span>Claude Code · linked reply</span></div><h2>May includes two more observations.</h2><p>The revised rule excludes rows only when ozone is missing. May changes from <b>24 to 26</b> observations; its mean changes from <b>24.125 to 23.615 ppb</b>.</p>{'' if compact else '<p class="quiet">August also changes. June, July and September stay the same.</p>'}<div class="links"><span>View comparison ↗</span><span>Open code ↗</span><span>Open figure ↗</span></div></div>'''
def context(): return '<div class="context-pill"><span class="sq">▦</span><span><b>Monthly ozone · May</b><small>Original result · month-05 · 1 row</small></span><span>×</span></div>'
def conversation():
    return '<div class="inspector-title">Agent <span>×</span></div><div class="session">Claude Code <span class="badge existing">In Rho</span></div><div class="bubble">五月为什么只有 24 条？只排除 Ozone 缺失值会怎样？</div><div class="step">✓ Read analysis.R</div><div class="step">✓ Changed the inclusion rule</div><div class="step">✓ Ran analysis.R</div><div class="reply-mini">May now has 26 observations.<br><span class="text-link">Open answer ↗</span></div><div class="composer">Ask a follow-up…<div>Attach context <span class="ui-btn primary">Send</span></div></div>'
def storyboard(title,scene,action,response,persist,cls=''):
    return f'<article class="story {cls}"><h3>{title}</h3><div class="story-screen">{scene}</div><div class="story-copy"><p><b>用户</b> {action}</p><p><b>反馈</b> {response}</p><p class="quiet"><b>保留</b> {persist}</p></div></article>'

# 01 — Direction
page('清晰的外壳，专业的插件', '01 / DIRECTION', '面向设计师的研究工作台设计稿 · 外壳、组件、插件模板与场景分镜',
    '<div class="cover-grid"><div><div class="large-number">Rho<span> / 01</span></div><h2 class="cover-title">从一个研究问题，<br>走到可检查的答案。</h2><p class="cover-copy">外壳负责找到工作、组织视图和保持连续性。插件负责把代码、数据、图形和 Agent 做得专业。结果与证据始终相连。</p><div class="pill-row">'+badge('新设计提案')+badge('基于真实 episode','existing')+badge('尚未做人测','neutral')+'</div><div class="cover-index">02–05　外壳与主应用组件<br>06–12　插件模板及实例<br>13–16　四组交互分镜<br>17–20　适配、视觉与交接</div></div><div class="cover-preview">'+app('<div class="workspace-content">'+tabs('Answer','Comparison','analysis.R')+answer()+frame('Monthly ozone',data_table(True),'Complete cases → Ozone available')+'</div>',cls='mini')+'<div class="caption">方向图：答案在工作区中；证据可展开；Agent 按需出现。</div></div></div>', 'cover')

